import { X, ChevronLeft } from 'lucide-react-native'
import { Text, TouchableOpacity, View } from 'react-native'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { useNavigation } from 'expo-router'

interface HeaderBarProps {
	title: string
	onClose: () => void
	showBackButton?: boolean
	showCloseButton?: boolean
}

export const HeaderBar = ({
	title,
	onClose,
	showBackButton,
	showCloseButton = true
}: HeaderBarProps) => {
	const navigation = useNavigation()

	const onBack = () => {
		navigation.canGoBack() && navigation.goBack()
	}

	const { theme } = useTheme()
	return (
		<View style={styles.headerBar}>
			{showBackButton && navigation.canGoBack() ? (
				<TouchableOpacity onPress={onBack}>
					<ChevronLeft
						size={24}
						color={colors[theme].gray[900]}
						style={styles.backIconStyle}
					/>
				</TouchableOpacity>
			) : (
				<X size={24} style={{ opacity: 0 }} />
			)}
			<Text style={styles.headerBarText(theme)}>{title}</Text>
			<TouchableOpacity
				style={{ opacity: showCloseButton ? 1 : 0 }}
				onPress={onClose}
			>
				<X
					size={24}
					color={colors[theme].gray[900]}
					style={styles.closeIconStyle}
				/>
			</TouchableOpacity>
		</View>
	)
}

const styles = defineStyles({
	backIconStyle: {
		transform: [{ translateX: -3 }]
	},
	closeIconStyle: {
		transform: [{ translateX: 2 }]
	},
	headerBar: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		paddingTop: 16
	},
	headerBarText: (theme: Theme) => ({
		fontSize: 18,
		fontWeight: '500',
		color: colors[theme].gray[900]
	})
})
